// Standalone Android check. Models are generated by make_npu_model.py --cpu-recurrent.
// INPUT and OUTPUT are interleaved stereo float32 PCM at 48 kHz.
#include <onnxruntime_cxx_api.h>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <numeric>
#include <span>
#include <stdexcept>
#include <string>
#include <string_view>
#include <unordered_map>
#include <vector>

namespace {

using Clock = std::chrono::steady_clock;
constexpr size_t kChannels = 2;
constexpr size_t kHopFrames = 128;
constexpr size_t kHopSamples = kChannels * kHopFrames;

size_t planar_index(size_t interleaved) {
    const size_t hop = interleaved / kHopSamples;
    const size_t sample = interleaved % kHopSamples;
    return hop * kHopSamples + (sample % kChannels) * kHopFrames + sample / kChannels;
}

double elapsed_ms(Clock::time_point start) {
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

Ort::SessionOptions options(bool qnn) {
    Ort::SessionOptions opts;
    opts.SetIntraOpNumThreads(1);
    opts.AddConfigEntry("session.intra_op.allow_spinning", "0");
    opts.DisableCpuMemArena();
    if (qnn) {
        opts.AddConfigEntry("session.disable_cpu_ep_fallback", "1");
        std::unordered_map<std::string, std::string> qnn_options{
            {"backend_path", "libQnnHtp.so"},
            {"enable_htp_fp16_precision", "1"},
        };
        if (const char* mode = std::getenv("ALLYSOUND_QNN_PERFORMANCE_MODE")) {
            qnn_options.emplace("htp_performance_mode", mode);
        }
        opts.AppendExecutionProvider("QNN", qnn_options);
    }
    return opts;
}

struct Input {
    std::vector<int64_t> shape;
    std::vector<float> data;
};

class Stage {
public:
    Stage(Ort::Env& env, const std::filesystem::path& file, bool qnn = false)
        : session_(env, file.c_str(), options(qnn)) {
        Ort::AllocatorWithDefaultOptions allocator;
        for (size_t i = 0; i < session_.GetInputCount(); ++i) {
            auto type = session_.GetInputTypeInfo(i);
            auto tensor = type.GetTensorTypeAndShapeInfo();
            inputs_.push_back({tensor.GetShape(), std::vector<float>(tensor.GetElementCount())});
            input_names_.emplace_back(session_.GetInputNameAllocated(i, allocator).get());
        }
        for (size_t i = 0; i < session_.GetOutputCount(); ++i) {
            output_names_.emplace_back(session_.GetOutputNameAllocated(i, allocator).get());
        }
        for (const auto& name : input_names_) input_ptrs_.push_back(name.c_str());
        for (const auto& name : output_names_) output_ptrs_.push_back(name.c_str());
    }

    std::span<float> input(std::string_view name) {
        auto it = std::find(input_names_.begin(), input_names_.end(), name);
        if (it == input_names_.end()) throw std::runtime_error("Unknown input " + std::string(name));
        return inputs_[it - input_names_.begin()].data;
    }

    void feed(std::string_view name, std::span<const float> value) {
        auto dest = input(name);
        if (value.size() != dest.size()) throw std::runtime_error("Incorrect tensor size for " + std::string(name));
        std::copy(value.begin(), value.end(), dest.begin());
    }

    Ort::Value run() {
        std::vector<Ort::Value> values;
        for (auto& in : inputs_) {
            values.push_back(Ort::Value::CreateTensor<float>(
                memory_, in.data.data(), in.data.size(), in.shape.data(), in.shape.size()));
        }
        const auto start = Clock::now();
        auto outputs = session_.Run(Ort::RunOptions{nullptr}, input_ptrs_.data(), values.data(), values.size(),
                                    output_ptrs_.data(), output_ptrs_.size());
        times_.push_back(elapsed_ms(start));
        // Output 0 is the block. Every other output carries a named state.
        for (size_t i = 1; i < outputs.size(); ++i) {
            const std::string_view name = output_names_[i];
            if (!name.starts_with("next_")) throw std::runtime_error("Unexpected state output");
            feed(name.substr(5), samples(outputs[i]));
        }
        return std::move(outputs.front());
    }

    static std::span<const float> samples(const Ort::Value& tensor) {
        return {tensor.GetTensorData<float>(), tensor.GetTensorTypeAndShapeInfo().GetElementCount()};
    }

    void report(std::string_view name) {
        const auto skip = times_.size() > 5 ? 5 : 0;
        const auto start = times_.begin() + skip;
        const auto count = times_.size() - skip;
        std::sort(start, times_.end());
        const auto sum = std::accumulate(start, times_.end(), 0.0);
        std::cout << name << " mean " << sum / count << " ms, p99 "
                  << start[count * 99 / 100] << " ms per block\n";
    }

private:
    Ort::MemoryInfo memory_ = Ort::MemoryInfo::CreateCpu(OrtDeviceAllocator, OrtMemTypeDefault);
    Ort::Session session_;
    std::vector<Input> inputs_;
    std::vector<std::string> input_names_, output_names_;
    std::vector<const char*> input_ptrs_, output_ptrs_;
    std::vector<double> times_;
};

} // namespace

int main(int argc, char** argv) {
    if (argc != 5 || (std::string_view(argv[1]) != "cpu" && std::string_view(argv[1]) != "qnn")) {
        std::cerr << "Usage: test_npu_decoder cpu|qnn MODEL_DIR INPUT.f32 OUTPUT.f32\n";
        return 2;
    }
    try {
        const std::filesystem::path dir(argv[2]);
        const bool qnn = std::string_view(argv[1]) == "qnn";
        Ort::Env env(ORT_LOGGING_LEVEL_WARNING, "AllySoundNPU");
        Stage pre(env, dir / "vocals_pre.onnx");
        Stage core(env, dir / "vocals_core.onnx");
        Stage decoder(env, dir / "vocals_decoder.onnx", qnn);
        Stage post(env, dir / "vocals_post.onnx");
        auto audio = pre.input("audio");
        if (audio.empty() || audio.size() % kHopSamples != 0) {
            throw std::runtime_error("Incorrect audio input size");
        }
        std::vector<float> io(audio.size());
        const auto block_bytes = static_cast<std::streamsize>(io.size() * sizeof(float));
        std::ifstream input(argv[3], std::ios::binary);
        std::ofstream output(argv[4], std::ios::binary);
        if (!input || !output) throw std::runtime_error("Cannot open PCM files");

        size_t blocks = 0;
        while (input.read(reinterpret_cast<char*>(io.data()), block_bytes)) {
            for (size_t i = 0; i < io.size(); ++i) {
                audio[planar_index(i)] = io[i];
            }
            core.feed("features", Stage::samples(pre.run()));
            decoder.feed("encoded", Stage::samples(core.run()));
            post.feed("mask", Stage::samples(decoder.run()));
            post.feed("audio", audio);
            auto result = post.run();
            auto separated = Stage::samples(result);
            if (separated.size() != io.size()) throw std::runtime_error("Incorrect audio output size");
            for (size_t i = 0; i < io.size(); ++i) {
                io[i] = separated[planar_index(i)];
                if (!std::isfinite(io[i])) throw std::runtime_error("Non-finite audio sample");
            }
            output.write(reinterpret_cast<const char*>(io.data()), block_bytes);
            ++blocks;
        }
        output.close();
        if (!input.eof() || input.gcount() % (kChannels * sizeof(float)) != 0 || blocks == 0 || !output) {
            throw std::runtime_error("PCM test failed or input contained no full blocks");
        }
        std::cout << blocks << " blocks (" << io.size() / kChannels << " frames each)\n";
        if (input.gcount()) std::cout << "Skipped partial final block\n";
        pre.report("Pre");
        core.report("Recurrent core");
        decoder.report(qnn ? "QNN decoder (CPU fallback disabled)" : "CPU decoder");
        post.report("Post");
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
